def _level_for(xp):
    """Salinan leveling.level_for saat migrasi dibuat (migrasi tidak boleh bergantung pada kode yang bisa berubah)."""
    level = 1
    while xp >= 100 * level + 25 * level * (level - 1):   # total XP untuk Level level+1
        level += 1
    return level


def grant_level_rewards(apps, schema_editor):
    """
    Akun lama: diamond yang sudah ada (bawaan 100) tetap, ditambah hadiah semua level yang sudah
    dicapai (naik ke Level n = 10·n, sama dengan shop.level_reward).
    """
    UserProfile = apps.get_model("gamification", "UserProfile")
    for p in UserProfile.objects.only("pk", "xp", "gems"):
        bonus = sum(10 * n for n in range(2, _level_for(p.xp) + 1))
        if bonus:
            UserProfile.objects.filter(pk=p.pk).update(gems=p.gems + bonus)


